import java.util.*;

class Solution {
    public int minStickers(String[] stickers, String target) {
        int n = target.length();
        int fullMask = (1 << n) - 1;
        int[][] stickerCounts = buildCounts(stickers);
        int[] dp = new int[1 << n];
        Arrays.fill(dp, n + 1);
        dp[0] = 0;

        for (int mask = 0; mask < (1 << n); mask++) {
            if (dp[mask] > n) {
                continue;
            }
            for (int[] sticker : stickerCounts) {
                int nextMask = applySticker(mask, sticker, target);
                if (nextMask != mask) {
                    dp[nextMask] = Math.min(dp[nextMask], dp[mask] + 1);
                }
            }
        }

        return dp[fullMask] > n ? -1 : dp[fullMask];
    }

    private int[][] buildCounts(String[] stickers) {
        int[][] counts = new int[stickers.length][26];
        for (int i = 0; i < stickers.length; i++) {
            for (char ch : stickers[i].toCharArray()) {
                counts[i][ch - 'a']++;
            }
        }
        return counts;
    }

    private int applySticker(int mask, int[] sticker, String target) {
        int[] available = sticker.clone();
        int nextMask = mask;
        for (int i = 0; i < target.length(); i++) {
            int letter = target.charAt(i) - 'a';
            if ((nextMask & (1 << i)) == 0 && available[letter] > 0) {
                available[letter]--;
                nextMask |= 1 << i;
            }
        }
        return nextMask;
    }
}

import java.util.*;

class Solution {
    private static final int INF = 1_000_000;

    public int minStickers(String[] stickers, String target) {
        int[][] stickerCounts = buildCounts(stickers);
        Map<String, Integer> memo = new HashMap<>();
        memo.put("", 0);
        int answer = dfs(sortLetters(target), stickerCounts, memo);
        return answer >= INF ? -1 : answer;
    }

    private int dfs(String target, int[][] stickerCounts, Map<String, Integer> memo) {
        if (memo.containsKey(target)) {
            return memo.get(target);
        }

        int[] need = countLetters(target);
        int best = INF;
        for (int[] sticker : stickerCounts) {
            if (sticker[target.charAt(0) - 'a'] == 0) {
                continue;
            }
            StringBuilder builder = new StringBuilder();
            for (int i = 0; i < 26; i++) {
                int remainingCount = Math.max(0, need[i] - sticker[i]);
                for (int k = 0; k < remainingCount; k++) {
                    builder.append((char) ('a' + i));
                }
            }
            String remaining = builder.toString();
            int sub = dfs(remaining, stickerCounts, memo);
            if (sub != INF) {
                best = Math.min(best, sub + 1);
            }
        }

        memo.put(target, best);
        return best;
    }

    private int[][] buildCounts(String[] stickers) {
        int[][] counts = new int[stickers.length][26];
        for (int i = 0; i < stickers.length; i++) {
            for (char ch : stickers[i].toCharArray()) {
                counts[i][ch - 'a']++;
            }
        }
        return counts;
    }

    private int[] countLetters(String word) {
        int[] count = new int[26];
        for (char ch : word.toCharArray()) {
            count[ch - 'a']++;
        }
        return count;
    }

    private String sortLetters(String word) {
        char[] chars = word.toCharArray();
        Arrays.sort(chars);
        return new String(chars);
    }
}

import java.util.*;

class Solution {
    private static final int INF = 1_000_000;
    private int[][] stickerCounts;
    private Map<String, Integer> memo;

    public int minStickers(String[] stickers, String target) {
        stickerCounts = buildCounts(stickers);
        int[] need = new int[26];
        for (char ch : target.toCharArray()) {
            need[ch - 'a']++;
        }
        memo = new HashMap<>();
        int answer = dfs(need);
        return answer >= INF ? -1 : answer;
    }

    private int dfs(int[] need) {
        String key = Arrays.toString(need);
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        int firstNeeded = firstNeededIndex(need);
        if (firstNeeded == -1) {
            return 0;
        }

        int best = INF;
        for (int[] sticker : stickerCounts) {
            if (sticker[firstNeeded] == 0) {
                continue;
            }
            int[] next = new int[26];
            for (int i = 0; i < 26; i++) {
                next[i] = Math.max(0, need[i] - sticker[i]);
            }
            int sub = dfs(next);
            if (sub != INF) {
                best = Math.min(best, sub + 1);
            }
        }

        memo.put(key, best);
        return best;
    }

    private int firstNeededIndex(int[] need) {
        for (int i = 0; i < 26; i++) {
            if (need[i] > 0) {
                return i;
            }
        }
        return -1;
    }

    private int[][] buildCounts(String[] stickers) {
        int[][] counts = new int[stickers.length][26];
        for (int i = 0; i < stickers.length; i++) {
            for (char ch : stickers[i].toCharArray()) {
                counts[i][ch - 'a']++;
            }
        }
        return counts;
    }
}

import java.util.*;

class Solution {
    public int minStickers(String[] stickers, String target) {
        int n = target.length();
        int fullMask = (1 << n) - 1;
        int[][] stickerCounts = buildCounts(stickers);
        int[] distance = new int[1 << n];
        Arrays.fill(distance, -1);
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        queue.add(0);
        distance[0] = 0;

        while (!queue.isEmpty()) {
            int mask = queue.removeFirst();
            for (int[] sticker : stickerCounts) {
                int nextMask = applyStickerToMask(mask, sticker, target);
                if (nextMask == mask || distance[nextMask] != -1) {
                    continue;
                }
                distance[nextMask] = distance[mask] + 1;
                if (nextMask == fullMask) {
                    return distance[nextMask];
                }
                queue.addLast(nextMask);
            }
        }

        return fullMask == 0 ? 0 : -1;
    }

    private int[][] buildCounts(String[] stickers) {
        int[][] counts = new int[stickers.length][26];
        for (int i = 0; i < stickers.length; i++) {
            for (char ch : stickers[i].toCharArray()) {
                counts[i][ch - 'a']++;
            }
        }
        return counts;
    }

    private int applyStickerToMask(int mask, int[] sticker, String target) {
        int[] available = sticker.clone();
        int nextMask = mask;
        for (int i = 0; i < target.length(); i++) {
            int letter = target.charAt(i) - 'a';
            if ((nextMask & (1 << i)) == 0 && available[letter] > 0) {
                available[letter]--;
                nextMask |= 1 << i;
            }
        }
        return nextMask;
    }
}

import java.util.*;

class Solution {
    private static final int INF = 1_000_000;
    private int[][] stickers;
    private int[] maxByChar;
    private List<Integer>[] candidateStickers;
    private Map<String, Integer> seen;
    private int best;

    public int minStickers(String[] stickers, String target) {
        int[][] rawCounts = buildCounts(stickers);
        this.stickers = removeDominatedStickers(rawCounts);
        int[] need = countTarget(target);

        maxByChar = new int[26];
        candidateStickers = new ArrayList[26];
        for (int i = 0; i < 26; i++) {
            candidateStickers[i] = new ArrayList<>();
        }
        for (int i = 0; i < this.stickers.length; i++) {
            for (int c = 0; c < 26; c++) {
                if (this.stickers[i][c] > 0) {
                    maxByChar[c] = Math.max(maxByChar[c], this.stickers[i][c]);
                    candidateStickers[c].add(i);
                }
            }
        }
        for (int c = 0; c < 26; c++) {
            if (need[c] > 0 && maxByChar[c] == 0) {
                return -1;
            }
        }

        best = INF;
        seen = new HashMap<>();
        dfs(need, 0);
        return best == INF ? -1 : best;
    }

    private void dfs(int[] need, int used) {
        if (isEmpty(need)) {
            best = Math.min(best, used);
            return;
        }
        int lowerBound = lowerBound(need);
        if (used + lowerBound >= best) {
            return;
        }

        String key = Arrays.toString(need);
        Integer previousUsed = seen.get(key);
        if (previousUsed != null && previousUsed <= used) {
            return;
        }
        seen.put(key, used);

        int pivot = choosePivot(need);
        for (int stickerIndex : candidateStickers[pivot]) {
            int[] sticker = stickers[stickerIndex];
            int[] next = need.clone();
            boolean changed = false;
            for (int c = 0; c < 26; c++) {
                int reduced = Math.max(0, next[c] - sticker[c]);
                if (reduced != next[c]) {
                    changed = true;
                }
                next[c] = reduced;
            }
            if (changed) {
                dfs(next, used + 1);
            }
        }
    }

    private int choosePivot(int[] need) {
        int pivot = -1;
        int fewestCandidates = Integer.MAX_VALUE;
        for (int c = 0; c < 26; c++) {
            if (need[c] > 0 && candidateStickers[c].size() < fewestCandidates) {
                fewestCandidates = candidateStickers[c].size();
                pivot = c;
            }
        }
        return pivot;
    }

    private int lowerBound(int[] need) {
        int bound = 0;
        for (int c = 0; c < 26; c++) {
            if (need[c] > 0) {
                bound = Math.max(bound, (need[c] + maxByChar[c] - 1) / maxByChar[c]);
            }
        }
        return bound;
    }

    private boolean isEmpty(int[] need) {
        for (int count : need) {
            if (count > 0) {
                return false;
            }
        }
        return true;
    }

    private int[][] removeDominatedStickers(int[][] rawCounts) {
        List<int[]> kept = new ArrayList<>();
        for (int i = 0; i < rawCounts.length; i++) {
            boolean dominated = false;
            for (int j = 0; j < rawCounts.length && !dominated; j++) {
                if (i != j && dominates(rawCounts[j], rawCounts[i], j < i)) {
                    dominated = true;
                }
            }
            if (!dominated) {
                kept.add(rawCounts[i]);
            }
        }
        return kept.toArray(new int[0][]);
    }

    private boolean dominates(int[] stronger, int[] weaker, boolean tieBreaksEqual) {
        boolean strictlyBetter = tieBreaksEqual;
        for (int c = 0; c < 26; c++) {
            if (stronger[c] < weaker[c]) {
                return false;
            }
            if (stronger[c] > weaker[c]) {
                strictlyBetter = true;
            }
        }
        return strictlyBetter;
    }

    private int[][] buildCounts(String[] stickers) {
        int[][] counts = new int[stickers.length][26];
        for (int i = 0; i < stickers.length; i++) {
            for (char ch : stickers[i].toCharArray()) {
                counts[i][ch - 'a']++;
            }
        }
        return counts;
    }

    private int[] countTarget(String target) {
        int[] need = new int[26];
        for (char ch : target.toCharArray()) {
            need[ch - 'a']++;
        }
        return need;
    }
}
